   506→	/**
   507→	 * Generates a poisson point set having N points constrained within a
   508→	 * rectangular region.
   509→	 * <p>
   510→	 * Poisson-disc sampling produces points that are tightly-packed, but no closer
   511→	 * to each other than a specified minimum distance, resulting in a more natural
   512→	 * and desirable pattern for many applications. This distribution is also
   513→	 * described as blue noise.
   514→	 * 
   515→	 * @param xMin x-coordinate of boundary minimum
   516→	 * @param yMin y-coordinate of boundary minimum
   517→	 * @param xMax x-coordinate of boundary maximum
   518→	 * @param yMax y-coordinate of boundary maximum
   519→	 * @param n    target size of poisson point set
   520→	 * @param seed number used to initialize the underlying pseudorandom number
   521→	 *             generator
   522→	 * @return
   523→	 */
   524→	public static List<PVector> poissonN(double xMin, double yMin, double xMax, double yMax, int n, long seed) {
   525→		final PoissonDistributionJRUS pd = new PoissonDistributionJRUS(seed);
   526→		return pd.generate(xMin, yMin, xMax, yMax, n);
   527→	}
