   529→	/**
   530→	 * Generates a set of points arranged in a phyllotaxis pattern (an arrangement
   531→	 * similar to the florets in the head of a sunflower), using the golden ratio
   532→	 * (the most irrational number) to position points with the least possible
   533→	 * aliasing (which is arguably the "best" arrangement).
   534→	 * 
   535→	 * @param centerX x coordinate of the center of the point set
   536→	 * @param centerY y coordinate of the center of the point set
   537→	 * @param n       number of points to generate
   538→	 * @param radius  radius of circular phyllotaxis extent (max distance of a point
   539→	 *                from the center position)
   540→	 * @return
   541→	 */
   542→	public static List<PVector> phyllotaxis(double centerX, double centerY, int n, double radius) {
   543→		return phyllotaxis(centerX, centerY, n, radius, 2 * Math.PI - GOLDEN_ANGLE);
   544→	}
   545→
   546→	/**
   547→	 * Generates a set of points arranged in a phyllotaxis pattern (an arrangement
   548→	 * similar to the florets in the head of a sunflower), using a user-defined
   549→	 * theta.
   550→	 * 
   551→	 * @param centerX x coordinate of the center of the point set
   552→	 * @param centerY y coordinate of the center of the point set
   553→	 * @param n       number of points to generate
   554→	 * @param radius  radius of circular phyllotaxis extent (max distance of a point
   555→	 *                from the center position)
   556→	 * @param theta   angle (in radians) to turn after each point placement
   557→	 * @return
   558→	 */
   559→	public static List<PVector> phyllotaxis(double centerX, double centerY, int n, double radius, double theta) {
   560→		final double fillArea = radius * radius * Math.PI; // calculate area to be filled
   561→		final double circleSpace = (fillArea / n); // area per circle
   562→		final double fudge = 0.7; // Fudge factor: breathing space between circles
   563→		final float circleRadius = (float) (Math.sqrt(circleSpace / Math.PI) * fudge);
   564→
   565→		float cumArea = 0; // cumulative circle area
   566→
   567→		final List<PVector> outList = new ArrayList<>();
   568→		for (int i = 1; i <= n; ++i) {
   569→			final double angle = i * theta; // rotation per circle
   570→			cumArea += circleSpace; // add sm_area to cum_area every loop
   571→
   572→			final double spiralR = Math.sqrt(cumArea / Math.PI); // expansion of spiral (distance of circle) per loop
   573→
   574→			float pX = (float) (centerX + Math.cos(angle) * spiralR); // spiral rotation of golden angle per loop on X
   575→			float pY = (float) (centerY + Math.sin(angle) * spiralR); // spiral rotation of golden angle per loop on Y
   576→
   577→			outList.add(new PVector(pX, pY, circleRadius));
   578→		}
   579→		return outList;
   580→	}
   581→
   582→	/**
   583→	 * Generates a set of deterministic stratified points (bounded by a rectangle)
   584→	 * from a low discrepancy sequence (LDS) based on an irrational number (the
   585→	 * plastic constant).
   586→	 * <p>
   587→	 * The <i>plastic LDS</i> has been <a href=
   588→	 * "http://extremelearning.com.au/unreasonable-effectiveness-of-quasirandom-sequences/">shown</a>
   589→	 * to have superior low discrepancy properties amongst the quasirandom
   590→	 * sequences, and is therefore recommended.
   591→	 * <p>
   592→	 * Low discrepancy sequences are deterministic (not randomized) number sequences
   593→	 * that are low discrepancy - meaning the points tend not to clump together and
   594→	 * leave holes; the resulting point set is more evenly spaced than a simple
   595→	 * random distribution but less regular than lattices.
   596→	 * 
   597→	 * @param xMin x-coordinate of boundary minimum
   598→	 * @param yMin y-coordinate of boundary minimum
   599→	 * @param xMax x-coordinate of boundary maximum
   600→	 * @param yMax y-coordinate of boundary maximum
   601→	 * @param n    number of points to generate
   602→	 * @return
   603→	 */
   604→	public static List<PVector> plasticLDS(double xMin, double yMin, double xMax, double yMax, int n) {
   605→		// https://github.com/Atrix256/SampleZoo/blob/master/src/families/_2d/samples/irrational_numbers/irrational_numbers.cpp
   606→		final double w = xMax - xMin;
   607→		final double h = yMax - yMin;
   608→		final double p = 1.32471795724474602596; // plastic constant
   609→		final double a1 = 1.0 / p; // inverse of plastic number
   610→		final double a2 = 1.0 / (p * p);
   611→
   612→		final List<PVector> points = new ArrayList<>(n);
   613→		for (int i = 0; i < n; i++) {
   614→			final float x = (float) (((0.5 + a1 * i) % 1) * w + xMin);
   615→			final float y = (float) (((0.5 + a2 * i) % 1) * h + yMin);
   616→			points.add(new PVector(x, y));
   617→		}
   618→		return points;
   619→	}
   620→
   621→	/**
   622→	 * Generates a set of deterministic stratified points (bounded by a rectangle)
   623→	 * from a low discrepancy sequence (LDS) based on an irrational number. In this
   624→	 * method, a random jitter is added to points to give the point set
   625→	 * blue-noise-like properties.
   626→	 * <p>
   627→	 * Low discrepancy sequences are deterministic (not randomized) number sequences
   628→	 * that are low discrepancy - meaning the points tend not to clump together and
   629→	 * leave holes; the resulting point set is more evenly spaced than a simple
   630→	 * random distribution but less regular than lattices.
   631→	 * 
   632→	 * @param xMin x-coordinate of boundary minimum
   633→	 * @param yMin y-coordinate of boundary minimum
   634→	 * @param xMax x-coordinate of boundary maximum
   635→	 * @param yMax y-coordinate of boundary maximum
   636→	 * @param n    number of points to generate
   637→	 * @return
   638→	 * @see #plasticJitteredLDS(double, double, double, double, int, long) seeded
   639→	 *      irrationalJitteredLDS()
   640→	 */
   641→	public static List<PVector> plasticJitteredLDS(double xMin, double yMin, double xMax, double yMax, int n) {
   642→		return plasticJitteredLDS(xMin, yMin, xMax, yMax, n, System.nanoTime());
   643→	}
   644→
   645→	/**
   646→	 * Generates a set of deterministic stratified points (bounded by a rectangle)
   647→	 * from a low discrepancy sequence (LDS) based on an irrational number. In this
   648→	 * method, a random jitter is added to points to give the point set
   649→	 * blue-noise-like properties.
   650→	 * <p>
   651→	 * Low discrepancy sequences are deterministic (not randomized) number sequences
   652→	 * that are low discrepancy - meaning the points tend not to clump together and
   653→	 * leave holes; the resulting point set is more evenly spaced than a simple
   654→	 * random distribution but less regular than lattices.
   655→	 * 
   656→	 * @param xMin x-coordinate of boundary minimum
   657→	 * @param yMin y-coordinate of boundary minimum
   658→	 * @param xMax x-coordinate of boundary maximum
   659→	 * @param yMax y-coordinate of boundary maximum
   660→	 * @param n    number of points to generate
   661→	 * @param seed number used to initialize the underlying pseudorandom number
   662→	 *             generator
   663→	 * @return
   664→	 * @see #plasticJitteredLDS(double, double, double, double, int) non-seeded
   665→	 *      irrationalJitteredLDS()
   666→	 */
   667→	public static List<PVector> plasticJitteredLDS(double xMin, double yMin, double xMax, double yMax, int n, long seed) {
   668→		// https://github.com/Atrix256/SampleZoo/blob/master/src/families/_2d/samples/irrational_numbers/irrational_numbers.cpp
   669→		final double w = xMax - xMin;
   670→		final double h = yMax - yMin;
   671→
   672→		final SplittableRandom random = new SplittableRandom(seed);
   673→		final double p = 1.32471795724474602596; // plastic constant
   674→		final double a1 = 1.0 / p;
   675→		final double a2 = 1.0 / (p * p);
   676→		final double c_magicNumber = 0.732;
   677→
   678→		final List<PVector> points = new ArrayList<>(n);
   679→		for (int i = 0; i < n; i++) {
   680→			final float x = (float) (((random.nextDouble() * c_magicNumber / Math.sqrt(i + 1d) + a1 * i) % 1) * w + xMin);
   681→			final float y = (float) (((random.nextDouble() * c_magicNumber / Math.sqrt(i + 1d) + a2 * i) % 1) * h + yMin);
   682→			points.add(new PVector(x, y));
   683→		}
   684→		return points;
   685→	}
   686→
   687→	/**
   688→	 * Generates a set of deterministic stratified points (bounded by a rectangle)
   689→	 * from a low discrepancy sequence (LDS) based on a Halton sequence.
   690→	 * <p>
   691→	 * Low discrepancy sequences are deterministic (not randomized) number sequences
   692→	 * that are low discrepancy - meaning the points tend not to clump together and
   693→	 * leave holes; the resulting point set is more evenly spaced than a simple
   694→	 * random distribution but less regular than lattices.
   695→	 * 
   696→	 * @param xMin x-coordinate of boundary minimum
   697→	 * @param yMin y-coordinate of boundary minimum
   698→	 * @param xMax x-coordinate of boundary maximum
   699→	 * @param yMax y-coordinate of boundary maximum
   700→	 * @param n    number of points to generate
   701→	 * @return
   702→	 */
   703→	public static List<PVector> haltonLDS(double xMin, double yMin, double xMax, double yMax, int n) {
   704→		final double w = xMax - xMin;
   705→		final double h = yMax - yMin;
   706→		float[][] values = new float[n][2];
   707→		vanDerCorput(values, 2, 0, true, 0);
   708→		vanDerCorput(values, 3, 1, true, 0);
   709→
   710→		final List<PVector> points = new ArrayList<>(n);
   711→		for (float[] point : values) {
   712→			points.add(new PVector((float) (point[0] * w + xMin), (float) (point[1] * h + yMin)));
   713→		}
   714→		return points;
   715→	}
   716→
   717→	/**
   718→	 * Generates a set of deterministic stratified points (bounded by a rectangle)
   719→	 * from a low discrepancy sequence (LDS) based on a Hammersley sequence.
   720→	 * <p>
   721→	 * The Hammersley sequence in 2D is just the 1d Van Der Corput sequence on one
   722→	 * axis, and regular sampling on the other axis.
   723→	 * <p>
   724→	 * Low discrepancy sequences are deterministic (not randomized) number sequences
   725→	 * that are low discrepancy - meaning the points tend not to clump together and
   726→	 * leave holes; the resulting point set is more evenly spaced than a simple
   727→	 * random distribution but less regular than lattices.
   728→	 * 
   729→	 * @param xMin x-coordinate of boundary minimum
   730→	 * @param yMin y-coordinate of boundary minimum
   731→	 * @param xMax x-coordinate of boundary maximum
   732→	 * @param yMax y-coordinate of boundary maximum
   733→	 * @param n    number of points to generate
   734→	 * @return
   735→	 */
   736→	public static List<PVector> hammersleyLDS(double xMin, double yMin, double xMax, double yMax, int n) {
   737→		final double w = xMax - xMin;
   738→		final double h = yMax - yMin;
   739→
   740→		float[][] values = new float[n][2];
   741→		vanDerCorput(values, 2, 0, false, 0);
   742→
   743→		final float offset = 1.0f / (n * 2);
   744→		for (int i = 0; i < n; ++i) {
   745→			values[i][1] = offset + (i / (float) n);
   746→		}
   747→
   748→		final List<PVector> points = new ArrayList<>(n);
   749→		for (float[] point : values) {
   750→			points.add(new PVector((float) (point[0] * w + xMin), (float) (point[1] * h + yMin)));
   751→		}
   752→		return points;
   753→	}
   754→
   755→	/**
   756→	 * Generates a set of random stratified points (bounded by a rectangle) based on
   757→	 * the "N-Rooks" sampling pattern.
   758→	 * <p>
   759→	 * N-Rooks is a sampling pattern where you treat the boundary as if it were a
   760→	 * chess board. Every sampling position is a rook that could move horizontally
   761→	 * or vertically, and should be placed such that none of these rooks could
   762→	 * capture/"see" any of the other rooks. In other words, every column has a
   763→	 * single sample point in it, and every row has a single sample point in it.
   764→	 * 
   765→	 * @param xMin x-coordinate of boundary minimum
   766→	 * @param yMin y-coordinate of boundary minimum
   767→	 * @param xMax x-coordinate of boundary maximum
   768→	 * @param yMax y-coordinate of boundary maximum
   769→	 * @param n    number of points to generate
   770→	 * @return
   771→	 * @see #nRooksLDS(double, double, double, double, int, long)
   772→	 */
   773→	public static List<PVector> nRooksLDS(double xMin, double yMin, double xMax, double yMax, int n) {
   774→		return nRooksLDS(xMin, yMin, xMax, yMax, n, System.nanoTime());
   775→	}
   776→
   777→	/**
   778→	 * Generates a set of random stratified points (bounded by a rectangle) based on
   779→	 * the "N-Rooks" sampling pattern.
   780→	 * <p>
   781→	 * N-Rooks is a sampling pattern where you treat the boundary as if it were a
   782→	 * chess board. Every sampling position is a rook that could move horizontally
   783→	 * or vertically, and should be placed such that none of these rooks could
   784→	 * capture/"see" any of the other rooks. In other words, every column has a
   785→	 * single sample point in it, and every row has a single sample point in it.
   786→	 * 
   787→	 * @param xMin x-coordinate of boundary minimum
   788→	 * @param yMin y-coordinate of boundary minimum
   789→	 * @param xMax x-coordinate of boundary maximum
   790→	 * @param yMax y-coordinate of boundary maximum
   791→	 * @param n    number of points to generate
   792→	 * @param seed number used to initialize the underlying pseudorandom number
   793→	 *             generator
   794→	 * @return
   795→	 * @see #nRooksLDS(double, double, double, double, int)
   796→	 */
   797→	public static List<PVector> nRooksLDS(double xMin, double yMin, double xMax, double yMax, int n, long seed) {
   798→		final double w = xMax - xMin;
   799→		final double h = yMax - yMin;
   800→
   801→		final List<Integer> rookPositions = IntStream.range(0, n).boxed().collect(Collectors.toList());
   802→		Collections.shuffle(rookPositions, new XoRoShiRo128PlusRandom(seed));
   803→
   804→		final float offset = 1.0f / (n * 2);
   805→
   806→		final List<PVector> points = new ArrayList<>(n);
   807→		for (int i = 0; i < n; i++) {
   808→			float x = offset + (rookPositions.get(i) / (float) n);
   809→			x *= w;
   810→			x += xMin;
   811→			float y = offset + i / (float) n;
   812→			y *= h;
   813→			y += yMin;
   814→			points.add(new PVector(x, y));
   815→		}
   816→
   817→		return points;
   818→	}
   819→
   820→	/**
   821→	 * Generates a 2D set of deterministic stratified points (bounded by a
   822→	 * rectangle) from the Sobol low discrepancy sequence (LDS).
   823→	 * <p>
   824→	 * A Sobol sequence is a low-discrepancy sequence with the property that for all
   825→	 * values of N,its subsequence (x1, ... xN) has a low discrepancy. It can be
   826→	 * used to generate pseudo-randompoints in a space S, which are
   827→	 * equi-distributed.
   828→	 * 
   829→	 * @param xMin x-coordinate of boundary minimum
   830→	 * @param yMin y-coordinate of boundary minimum
   831→	 * @param xMax x-coordinate of boundary maximum
   832→	 * @param yMax y-coordinate of boundary maximum
   833→	 * @param n    number of points to generate
   834→	 * @since 1.3.1
   835→	 * @return
   836→	 */
   837→	public static List<PVector> sobolLDS(double xMin, double yMin, double xMax, double yMax, int n) {
   838→		final double w = xMax - xMin;
   839→		final double h = yMax - yMin;
   840→		final int dimension = 2;
   841→		final int BITS = 52;
   842→		final double SCALE = FastMath.pow(2, BITS);
   843→		final long[][] direction = new long[dimension][BITS + 1];
   844→		final long[] x = new long[dimension];
   845→		final int[] m = new int[] { 0, 1 };
   846→		final int a = 0;
   847→		final int s = m.length - 1;
   848→
   849→		for (int i = 1; i <= BITS; i++) {
   850→			direction[0][i] = 1l << (BITS - i);
   851→		}
   852→
   853→		// init direction vector
   854→		final int d = 1;
   855→		for (int i = 1; i <= s; i++) {
   856→			direction[d][i] = ((long) m[i]) << (BITS - i);
   857→		}
   858→		for (int i = s + 1; i <= BITS; i++) {
   859→			direction[d][i] = direction[d][i - s] ^ (direction[d][i - s] >> s);
   860→			for (int k = 1; k <= s - 1; k++) {
   861→				direction[d][i] ^= ((a >> (s - 1 - k)) & 1) * direction[d][i - k];
   862→			}
   863→		}
   864→
   865→		List<PVector> output = new ArrayList<>(n);
   866→		for (int i = 1; i < n; i++) {
   867→
   868→			// find the index c of the rightmost 0
   869→			int c = 1;
   870→			int value = i - 1;
   871→			while ((value & 1) == 1) {
   872→				value >>= 1;
   873→				c++;
   874→			}
   875→
   876→			x[0] ^= direction[0][c];
   877→			x[1] ^= direction[1][c];
   878→			double vX = x[0] / SCALE;
   879→			vX *= w;
   880→			vX += xMin;
   881→			double vY = x[1] / SCALE;
   882→			vY *= h;
   883→			vY += yMin;
   884→			output.add(new PVector((float) vX, (float) vY));
   885→		}
   886→
   887→		return output;
   888→	}
   889→
   890→	/**
   891→	 * Computes the <i>Euclidean minimum spanning tree</i> (EMST) of a set of
   892→	 * points.
   893→	 * <p>
   894→	 * The EMST is a system of line segments, having only the given points as their
   895→	 * endpoints, whose union includes all of the points in a connected set, and
   896→	 * which has the minimum possible total length of any such system.
   897→	 * 
   898→	 * @param points the set of points over which to compute the EMST
   899→	 * @return a LINES PShape
   900→	 * @since 1.3.0
   901→	 */
   902→	public static PShape minimumSpanningTree(List<PVector> points) {
   903→		/*
   904→		 * The Euclidean minimum spanning tree in a plane is a subgraph of the Delaunay
   905→		 * triangulation.
   906→		 */
   907→		IIncrementalTin triangulation = PGS_Triangulation.delaunayTriangulationMesh(points);
   908→		SimpleGraph<PVector, PEdge> graph = PGS_Triangulation.toGraph(triangulation);
   909→		SpanningTreeAlgorithm<PEdge> st = new PrimMinimumSpanningTree<>(graph); // faster than kruskal algorithm
   910→		return PGS_SegmentSet.toPShape(st.getSpanningTree().getEdges());
   911→	}
   912→
   913→	/**
   914→	 * Computes the hilbert index of a coordinate on a hilbert curve of order n.
   915→	 */
   916→	private static int xy2Hilbert(final int px, final int py, final int n) {
   917→		int i, xi, yi;
   918→		int s, temp;
   919→
   920→		int x = px;
   921→		int y = py;
   922→		s = 0; // Initialize.
   923→		for (i = n - 1; i >= 0; i--) {
   924→			xi = (x >> i) & 1; // Get bit i of x.
   925→			yi = (y >> i) & 1; // Get bit i of y.
   926→
   927→			if (yi == 0) {
   928→				temp = x; // Swap x and y and,
   929→				x = y ^ (-xi); // if xi = 1,
   930→				y = temp ^ (-xi); // complement them.
   931→			}
   932→			s = 4 * s + 2 * xi + (xi ^ yi); // Append two bits to s.
   933→		}
   934→		return s;
   935→	}
   936→
   937→	/**
   938→	 * @param values
   939→	 * @param base
   940→	 * @param axis         0 = x axis; 1 = y axis
   941→	 * @param skipZero
   942→	 * @param truncateBits
   943→	 */
   944→	private static void vanDerCorput(float[][] values, int base, int axis, boolean skipZero, int truncateBits) {
   945→		// https://blog.demofox.org/2017/05/29/when-random-numbers-are-too-random-low-discrepancy-sequences/
   946→		// https://github.com/Atrix256/SampleZoo/blob/master/src/families/_2d/samples/lds/LDS.cpp
   947→		// figure out how many bits we are working in.
   948→		int n = values.length;
   949→		int value = 1;
   950→		int numBits = 0;
   951→		while (value < n) {
   952→			value *= 2;
   953→			++numBits;
   954→		}
   955→		int numBitsPreserved = numBits - truncateBits;
   956→		int bitsPreservedMask = numBitsPreserved > 0 ? (1 << numBitsPreserved) - 1 : 0;
   957→
   958→		for (int i = 0; i < n; ++i) {
   959→			values[i][axis] = 0.0f;
   960→			float denominator = base;
   961→			int q = i + (skipZero ? 1 : 0);
   962→			q &= bitsPreservedMask;
   963→			while (q > 0) {
   964→				int multiplier = q % base;
   965→				values[i][axis] += multiplier / denominator;
   966→				q = q / base;
   967→				denominator *= base;
   968→			}
   969→		}
   970→	}
   971→
   972→	private static class CPVector implements Clusterable {
   973→		final PVector p;
   974→		final double[] point;
   975→
   976→		CPVector(PVector p) {
   977→			this.p = p;
   978→			point = new double[] { p.x, p.y };
   979→		}
   980→
   981→		@Override
   982→		public double[] getPoint() {
   983→			return point;
   984→		}
   985→	}
   986→
   987→}
